('3ac8b84f1cc29180d74a9a57786193e201a832bf', 'docs/DOC_INGESTION_PLAN.md', 'DOC INGESTION PLAN', NULL, 'paragraph', 'Paragraph', 'Suggested Defaults - FACTCHECK_THRESHOLD = 0.82 - MAX_CONCEPT_TEXT_CHARS = 2000 - MAX_SOURCE_EXCERPT_CHARS = 1000 - NEAR_DUPLICATE_SIMILARITY = 0.97 - SOURCE_SPAN_OVERLAP_DUPLICATE = 0.70 - DB_TRANSACTION_SCOPE = per_document - BATCH_HISTORY_MIN = 3 - PARSER_FAIL_MODE = fail_closed_per_document', '{"type":"paragraph"}', 14926, 15221, 'Suggested Defaults - FACTCHECK_THRESHOLD = 0.82 - MAX_CONCEPT_TEXT_CHARS = 2000 - MAX_SOURCE_EXCERPT_CHARS = 1000 - NEAR_DUPLICATE_SIMILARITY = 0.97 - SOURCE_SPAN_OVERLAP_DUPLICATE = 0.70 - DB_TRANSACTION_SCOPE = per_document - BATCH_HISTORY_MIN = 3 - PARSER_FAIL_MODE = fail_closed_per_document', 'Suggested Defaults - FACTCHECK_THRESHOLD = 0.82 - MAX_CONCEPT_TEXT_CHARS = 2000 - MAX_SOURCE_EXCERPT_CHARS = 1000 - NEAR_DUPLICATE_SIMILARITY = 0.97 - SOURCE_SPAN_OVERLAP_DUPLICATE = 0.70 - DB_TRANSACTION_SCOPE = per_document - BATCH_HISTORY_MIN = 3 - PARSER_FAIL_MODE = fail_closed_per_document', 0.9, 'pass', '', 14926, 15221, 'Suggested Defaults - FACTCHECK_THRESHOLD = 0.82 - MAX_CONCEPT_TEXT_CHARS = 2000 - MAX_SOURCE_EXCERPT_CHARS = 1000 - NEAR_DUPLICATE_SIMILARITY = 0.97 - SOURCE_SPAN_OVERLAP_DUPLICATE = 0.70 - DB_TRANSACTION_SCOPE = per_document - BATCH_HISTORY_MIN = 3 - PARSER_FAIL_MODE = fail_closed_per_document', 'Suggested Defaults - FACTCHECK_THRESHOLD = 0.82 - MAX_CONCEPT_TEXT_CHARS = 2000 - MAX_SOURCE_EXCERPT_CHARS = 1000 - NEAR_DUPLICATE_SIMILARITY = 0.97 - SOURCE_SPAN_OVERLAP_DUPLICATE = 0.70 - DB_TRANSACTION_SCOPE = per_document - BATCH_HISTORY_MIN = 3 - PARSER_FAIL_MODE = fail_closed_per_document', 0, 0, 'manual-doc_ingestion_plan-20260330T214721700Z', '3b885331648432ed029bf50ef9a055a0842f6003cc0a8bee05eafb43dbc14131', 'c01ec6e81d7453592a6a00e6e911d29102741e780f48436be46bea7745130179', 1, 'manual-v1', 'none', datetime('now')),
