('151e692df710ff8a933c8ddb9d3e7e7af592fcbc', 'docs\DOC_INGESTION_PLAN.md', 'DOC INGESTION PLAN', NULL, 'paragraph', 'Paragraph', 'SELECT concept_id, doc_path, concept_title, concept_text FROM docs_concepts WHERE active = 1 AND soft_deleted = 0 AND factcheck_status = ''pass'' AND concept_type IN (''api'', ''procedure_step'', ''warning'', ''fact'', ''note'') ORDER BY created_at DESC LIMIT 50;', '{"type":"paragraph"}', 14014, 14271, 'SELECT concept_id, doc_path, concept_title, concept_text FROM docs_concepts WHERE active = 1 AND soft_deleted = 0 AND factcheck_status = ''pass'' AND concept_type IN (''api'', ''procedure_step'', ''warning'', ''fact'', ''note'') ORDER BY created_at DESC LIMIT 50;', 'SELECT concept_id, doc_path, concept_title, concept_text FROM docs_concepts WHERE active = 1 AND soft_deleted = 0 AND factcheck_status = ''pass'' AND concept_type IN (''api'', ''procedure_step'', ''warning'', ''fact'', ''note'') ORDER BY created_at DESC LIMIT 50;', 0.9, 'pass', '', 14014, 14271, 'SELECT concept_id, doc_path, concept_title, concept_text FROM docs_concepts WHERE active = 1 AND soft_deleted = 0 AND factcheck_status = ''pass'' AND concept_type IN (''api'', ''procedure_step'', ''warning'', ''fact'', ''note'') ORDER BY created_at DESC LIMIT 50;', 'SELECT concept_id, doc_path, concept_title, concept_text FROM docs_concepts WHERE active = 1 AND soft_deleted = 0 AND factcheck_status = ''pass'' AND concept_type IN (''api'', ''procedure_step'', ''warning'', ''fact'', ''note'') ORDER BY created_at DESC LIMIT 50;', 0, 0, 'manual-doc_ingestion_plan-20260330T214856170Z', '3b885331648432ed029bf50ef9a055a0842f6003cc0a8bee05eafb43dbc14131', '75d32662a2ef81e5deb397f89db2657753e2b9966fa2eaa53d1f972f2c6fcbe9', 1, 'manual-v1', 'none', datetime('now')),
