('4a05e1b5f1e9c370e3549f301fbe8f2a5e96a2f4', 'docs\DOC_INGESTION_PLAN.md', 'DOC INGESTION PLAN', NULL, 'paragraph', 'Paragraph', 'Required flow: 1. begin transaction 2. parse, extract, normalize, dedupe, and fact-check the full document candidate set 3. insert the new batch rows with active = 0 or in a non-promoted state 4. validate that all required inserts succeeded and no uniqueness or integrity constraint failed 5. deactivate prior active rows for the same doc_path 6. promote the new rows for that doc_path to active = 1 7. commit', '{"type":"paragraph"}', 14325, 14734, 'Required flow: 1. begin transaction 2. parse, extract, normalize, dedupe, and fact-check the full document candidate set 3. insert the new batch rows with active = 0 or in a non-promoted state 4. validate that all required inserts succeeded and no uniqueness or integrity constraint failed 5. deactivate prior active rows for the same doc_path 6. promote the new rows for that doc_path to active = 1 7. commit', 'Required flow: 1. begin transaction 2. parse, extract, normalize, dedupe, and fact-check the full document candidate set 3. insert the new batch rows with active = 0 or in a non-promoted state 4. validate that all required inserts succeeded and no uniqueness or integrity constraint failed 5. deactivate prior active rows for the same doc_path 6. promote the new rows for that doc_path to active = 1 7. commit', 0.9, 'pass', '', 14325, 14734, 'Required flow: 1. begin transaction 2. parse, extract, normalize, dedupe, and fact-check the full document candidate set 3. insert the new batch rows with active = 0 or in a non-promoted state 4. validate that all required inserts succeeded and no uniqueness or integrity constraint failed 5. deactivate prior active rows for the same doc_path 6. promote the new rows for that doc_path to active = 1 7. commit', 'Required flow: 1. begin transaction 2. parse, extract, normalize, dedupe, and fact-check the full document candidate set 3. insert the new batch rows with active = 0 or in a non-promoted state 4. validate that all required inserts succeeded and no uniqueness or integrity constraint failed 5. deactivate prior active rows for the same doc_path 6. promote the new rows for that doc_path to active = 1 7. commit', 0, 0, 'manual-doc_ingestion_plan-20260330T214856170Z', '3b885331648432ed029bf50ef9a055a0842f6003cc0a8bee05eafb43dbc14131', '399e9f6412a5f141a53de8739ec52c10a5475dab314547c9e9b41f5f73af5813', 1, 'manual-v1', 'none', datetime('now')),
('ba293e71043f253689839894df5f00e554c105eb', 'docs\DOC_INGESTION_PLAN.md', 'DOC INGESTION PLAN', NULL, 'paragraph', 'Paragraph', 'If any step fails: - roll back the transaction - keep the prior active version unchanged', '{"type":"paragraph"}', 14736, 14824, 'If any step fails: - roll back the transaction - keep the prior active version unchanged', 'If any step fails: - roll back the transaction - keep the prior active version unchanged', 0.9, 'pass', '', 14736, 14824, 'If any step fails: - roll back the transaction - keep the prior active version unchanged', 'If any step fails: - roll back the transaction - keep the prior active version unchanged', 0, 0, 'manual-doc_ingestion_plan-20260330T214856170Z', '3b885331648432ed029bf50ef9a055a0842f6003cc0a8bee05eafb43dbc14131', 'ae3aeabc4ed782e6596e1e3093be91ddb40a5d866f7e227e316f93dd88afc09f', 1, 'manual-v1', 'none', datetime('now')),
